export function parseCsvLine(line) {
  const fields = [];
  let current = '';
  let inQuotes = false;
  let i = 0;

  while (i < line.length) {
    const char = line[i];

    if (inQuotes) {
      if (char === '"') {
        if (i + 1 < line.length && line[i + 1] === '"') {
          current += '"';
          i += 2;
        } else {
          inQuotes = false;
          i += 1;
        }
      } else {
        current += char;
        i += 1;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
        i += 1;
      } else if (char === ',') {
        fields.push(current);
        current = '';
        i += 1;
      } else {
        current += char;
        i += 1;
      }
    }
  }

  fields.push(current);
  return fields;
}

export function deepMerge(base, override) {
  const result = {};
  const keys = new Set([...Object.keys(base), ...Object.keys(override)]);

  for (const key of keys) {
    if (key in override) {
      const overrideVal = override[key];
      const baseVal = base[key];
      if (isPlainObject(overrideVal) && isPlainObject(baseVal)) {
        result[key] = deepMerge(baseVal, overrideVal);
      } else {
        result[key] = overrideVal;
      }
    } else {
      result[key] = base[key];
    }
  }

  return result;
}

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

const TO_ROMAN = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I'],
];

const FROM_ROMAN = {
  I: 1,
  V: 5,
  X: 10,
  L: 50,
  C: 100,
  D: 500,
  M: 1000,
};

const ROMAN_RE = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999');
  }
  let result = '';
  for (const [value, symbol] of TO_ROMAN) {
    while (n >= value) {
      result += symbol;
      n -= value;
    }
  }
  return result;
}

export function fromRoman(s) {
  if (typeof s !== 'string' || !s.length || !ROMAN_RE.test(s)) {
    throw new Error('Invalid Roman numeral');
  }
  let total = 0;
  let prev = 0;
  for (let i = s.length - 1; i >= 0; i--) {
    const current = FROM_ROMAN[s[i]];
    if (current < prev) {
      total -= current;
    } else {
      total += current;
      prev = current;
    }
  }
  return total;
}
